"""UI wiring tests in Chromium. Host API is simulated; runtime engine has separate
real-browser tests. The graph fixture is the actual recorded runtime export.
"""
import argparse,base64,json,os,shutil,subprocess
from pathlib import Path
from playwright.sync_api import sync_playwright
R=Path(__file__).resolve().parents[1]
p=argparse.ArgumentParser();p.add_argument('--output',default='/mnt/data/cfl070-runtime-ui');p.add_argument('--evidence',default='/mnt/data/cfl070-test/observed-runtime.cfl.json');args=p.parse_args();out=Path(args.output);out.mkdir(parents=True,exist_ok=True);checks=[]
def ok(s):checks.append(s);print('PASS',s,flush=True)
def uri(p):return 'data:text/javascript;base64,'+base64.b64encode(p.read_bytes()).decode()
def html(module,values):return subprocess.check_output(['node','-e',f"process.stdout.write(require('./{module}')."+('runtimeHtml' if 'runtime/' in module else 'webviewHtml')+"(JSON.parse(process.argv[1])))",json.dumps(values)],cwd=R).decode()
with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path=shutil.which('chromium'),headless=True,args=['--no-sandbox'])
 page=b.new_page(viewport={'width':1440,'height':1000});errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.evaluate("window.__messages=[];window.acquireVsCodeApi=()=>({postMessage:m=>window.__messages.push(m),getState:()=>({}),setState:()=>{}})")
 page.set_content(html('runtime/view',{'scriptUri':uri(R/'media/runtime.js')}),wait_until='load');assert page.locator('#snapshot').is_disabled();assert len(page.evaluate('window.__messages'))==0;assert page.locator('input:checked').count()==0;ok('Runtime UI does not record or authorize captures automatically')
 page.locator('#captureState').check();page.locator('#captureVisual').check();page.locator('#start').click();messages=page.evaluate('window.__messages');assert messages[-1]['command']=='start';assert messages[-1]['options']['captureState'];assert not messages[-1]['options']['captureBodies'];assert page.locator('#start').is_disabled();ok('Start posts explicit capture flags; controls stay disabled while starting')
 page.evaluate("window.postMessage({type:'runtime:result',sessionId:'test',result:{started:true}},'*')");page.wait_for_timeout(30);page.locator('#snapshot').click();assert page.evaluate('window.__messages.at(-1).command')=='snapshot';page.evaluate("window.postMessage({type:'runtime:result',sessionId:'test',result:{snapshotId:'a',text:'<img src=x onerror=alert(1)>'}},'*')");page.wait_for_timeout(30);assert page.locator('#output img').count()==0;ok('Observation results render as text rather than executable HTML')
 image=base64.b64encode((Path(args.evidence).parent/'runtime-after.png').read_bytes()).decode();page.locator('#screenshot').click();page.evaluate('(image)=>window.postMessage({type:"runtime:result",sessionId:"test",image,result:{mimeType:"image/png"}},"*")',image);page.wait_for_timeout(60);assert page.locator('#image').is_visible();page.screenshot(path=str(out/'runtime-observer.png'));ok('Explicit PNG capture displays under nonce/data-image CSP')
 page.locator('#stop').click();page.evaluate("window.postMessage({type:'runtime:result',sessionId:null,result:{closed:true}},'*')");page.wait_for_timeout(30);assert not page.locator('#image').is_visible();assert page.locator('#snapshot').is_disabled();ok('Stop removes screenshot and deactivates observation controls')
 page.close();page=b.new_page(viewport={'width':1680,'height':1040});page.on('pageerror',lambda e:errors.append(str(e)));page.evaluate("window.__messages=[];window.acquireVsCodeApi=()=>({postMessage:m=>window.__messages.push(m),getState:()=>({}),setState:()=>{}})");style='data:text/css;base64,'+base64.b64encode((R/'media/graph.css').read_bytes()).decode();page.set_content(html('lib/webview-html',{'scriptUri':uri(R/'media/graph.js'),'styleUri':style,'cspSource':'data:'}),wait_until='load');page.wait_for_function("window.__messages.some(m=>m.command==='ready')")
 data=json.loads(Path(args.evidence).read_text());page.evaluate('(s)=>window.postMessage({type:"flow:state",epoch:1,graph:s.graph,cards:s.cards||{}},"*")',data);page.wait_for_timeout(100);assert 'OBSERVED RUNTIME' in page.locator('#status').inner_text();assert page.locator('#origin').inner_text()=='Earlier';assert page.locator('#destination').inner_text()=='Later';assert page.locator('#refresh').is_disabled();assert page.locator('#walk').is_disabled();assert page.locator('.node').count()>5;ok('Actual runtime export renders as chronology, not causal/static execution graph')
 page.locator('#origin').click();page.locator('#allPaths').click();page.locator('#fit').click();page.screenshot(path=str(out/'runtime-timeline.png'));page.locator('#runtime').click();assert page.evaluate("window.__messages.some(m=>m.command==='runtime')");assert not errors,errors;ok('Earlier/Later navigation and Runtime toolbar wire correctly without JS errors')
 b.close()
(out/'results.json').write_text(json.dumps({'passed':len(checks),'checks':checks},indent=2));print('Passed',len(checks),'runtime UI checks')
